#!/usr/bin/env node
/**
 * One-shot retrofitter for already-published deck.html files: injects the
 * worksheet-clamp runtime + HTML attribution element introduced in
 * catalog-export.js post-345-en-wave session.
 *
 * Background: the operator's 345-en-wave (alphabet-train + math-worksheet +
 * prepositions) decks were generated by an older catalog-export.js that did
 * NOT include the clamp logic. Their deck.html files render the full US
 * Letter portrait JPEG (612x792) including the empty bottom area, producing
 * a visible whitespace gap between the worksheet content and the Check
 * Answers button. catalog-export.js update (this commit) emits the clamp
 * runtime for FUTURE generations. This script retrofits the runtime into
 * the existing 307+ deck.html files so the gap is fixed without regenerating
 * decks.
 *
 * Mechanism: the script reads each deck.html file, looks for the clamp
 * marker comment (idempotency guard); if absent, injects a new <script>
 * block containing the same lcsClampWorksheet + lcsInjectAttribHtml logic
 * + .lcs-attrib-html CSS that catalog-export.js now emits at deck-generation
 * time. The injection is placed immediately before </body> so it runs after
 * the deck's main runtime has positioned interactive elements.
 *
 * Idempotent: marker comment "<!-- lcs-clamp-injected-v1 -->" prevents
 * double-injection on re-runs.
 *
 * Usage:
 *   node scripts/publish-cli/inject-clamp.js <directory> [--dry-run]
 *
 * Where <directory> is e.g. /var/www/lcs-media/decks/en (script walks each
 * <slug>-v1/deck.html). For multi-locale: run per locale, or pass the
 * /var/www/lcs-media/decks/ root.
 *
 * Atomic per-file write (tmp + rename). No backups (in-place + idempotent).
 */

'use strict';

var fs = require('fs');
var path = require('path');

var MARKER = '<!-- lcs-clamp-injected-v1 -->';

// Stand-alone clamp+attribution snippet. Mirrors the catalog-export.js
// emission inside buildEmbedAffordance. Self-contained so it can be safely
// inserted into any existing deck.html that follows the standard structure
// (.lcs-worksheet > .lcs-worksheet__img + .lcs-overlay).
var CLAMP_SCRIPT = '\n' + MARKER + '\n' +
'<script>(function(){\n' +
'"use strict";\n' +
'function lcsInjectAttribHtml(){\n' +
'  if(document.querySelector(".lcs-attrib-html"))return;\n' +
'  var wrap=document.querySelector(".lcs-worksheet-wrap");\n' +
'  if(!wrap||!wrap.parentNode)return;\n' +
'  var p=document.createElement("p");\n' +
'  p.className="lcs-attrib-html";\n' +
'  var a=document.createElement("a");\n' +
'  a.href="https://lessoncraftstudio.com";\n' +
'  a.target="_blank";\n' +
'  a.rel="noopener noreferrer";\n' +
'  a.textContent="Made with LessonCraftStudio.com";\n' +
'  p.appendChild(a);\n' +
'  wrap.parentNode.insertBefore(p,wrap.nextSibling);\n' +
'}\n' +
'function lcsClampWorksheet(){\n' +
'  var ws=document.querySelector(".lcs-worksheet");\n' +
'  if(!ws)return;\n' +
'  var img=ws.querySelector(".lcs-worksheet__img");\n' +
'  if(img&&!img.naturalHeight){if(!img.lcsClampWired){img.lcsClampWired=true;img.addEventListener("load",lcsClampWorksheet);}return;}\n' +
'  var imgH=img?img.offsetHeight:0;\n' +
'  var overlay=ws.querySelector(".lcs-overlay");\n' +
'  if(overlay&&imgH>0){overlay.style.height=imgH+"px";}\n' +
'  var els=ws.querySelectorAll(".lcs-cell,.lcs-piece,.lcs-slot,.lcs-img-overlay,[data-rect]");\n' +
'  if(!els.length&&overlay&&overlay.children.length){els=overlay.children;}\n' +
'  var wsRect=ws.getBoundingClientRect();\n' +
'  var maxBottom=0;\n' +
'  for(var i=0;i<els.length;i++){var r=els[i].getBoundingClientRect();var b=r.bottom-wsRect.top;if(b>maxBottom)maxBottom=b;}\n' +
'  if(maxBottom<=0)return;\n' +
'  var pad=24;\n' +
'  var clamped=maxBottom+pad;\n' +
'  if(imgH>0&&clamped>=imgH-pad)return;\n' +
'  ws.style.height=clamped+"px";\n' +
'  ws.style.overflow="hidden";\n' +
'}\n' +
'var lcsAttribStyle=document.createElement("style");\n' +
'lcsAttribStyle.textContent=".lcs-attrib-html{text-align:center;margin:8px 0 16px;font-size:11px;color:#999;line-height:1.3}.lcs-attrib-html a{color:#999;text-decoration:none}.lcs-attrib-html a:hover{text-decoration:underline}";\n' +
'document.head.appendChild(lcsAttribStyle);\n' +
'function lcsInitClampAndAttrib(){lcsInjectAttribHtml();lcsClampWorksheet();}\n' +
'if(document.readyState==="complete")lcsInitClampAndAttrib();\n' +
'else window.addEventListener("load",lcsInitClampAndAttrib);\n' +
'window.addEventListener("resize",lcsClampWorksheet);\n' +
'})();</script>\n';

function processFile(filepath, dryRun) {
  var html;
  try {
    html = fs.readFileSync(filepath, 'utf8');
  } catch (e) {
    return { file: filepath, action: 'skip-read-error', note: e.message };
  }
  if (html.indexOf(MARKER) !== -1) {
    return { file: filepath, action: 'skip-already-injected' };
  }
  // Insert immediately before </body>. Tolerant to whitespace.
  var bodyClose = html.lastIndexOf('</body>');
  if (bodyClose === -1) {
    return { file: filepath, action: 'skip-no-body-close' };
  }
  var newHtml = html.slice(0, bodyClose) + CLAMP_SCRIPT + html.slice(bodyClose);
  if (dryRun) {
    return { file: filepath, action: 'would-inject' };
  }
  var tmp = filepath + '.tmp';
  try {
    fs.writeFileSync(tmp, newHtml, 'utf8');
    fs.renameSync(tmp, filepath);
  } catch (e) {
    try { fs.unlinkSync(tmp); } catch (_) {}
    return { file: filepath, action: 'write-error', note: e.message };
  }
  return { file: filepath, action: 'injected' };
}

function walkDecksDir(rootDir, accumulator) {
  var entries;
  try {
    entries = fs.readdirSync(rootDir);
  } catch (e) {
    return;
  }
  entries.forEach(function (name) {
    if (name.charAt(0) === '.') return; // skip dot-dirs (.archived, etc.)
    var p = path.join(rootDir, name);
    var stat;
    try { stat = fs.statSync(p); } catch (_) { return; }
    if (!stat.isDirectory()) return;
    // Two recognized shapes:
    //   1. <root>/<slug>-v1/deck.html  (single-locale dir passed as root)
    //   2. <root>/<locale>/<slug>-v1/deck.html  (multi-locale root)
    var deckHtml = path.join(p, 'deck.html');
    if (fs.existsSync(deckHtml)) {
      accumulator.push(deckHtml);
    } else {
      walkDecksDir(p, accumulator);
    }
  });
}

function main() {
  var args = process.argv.slice(2);
  var dryRun = false;
  var rootDir = null;
  for (var i = 0; i < args.length; i++) {
    if (args[i] === '--dry-run') { dryRun = true; continue; }
    if (args[i].charAt(0) === '-') {
      console.error('ERROR: unknown flag "' + args[i] + '"');
      process.exit(2);
    }
    if (rootDir == null) { rootDir = args[i]; continue; }
    console.error('ERROR: unexpected positional argument "' + args[i] + '"');
    process.exit(2);
  }
  if (!rootDir) {
    console.error('USAGE: node scripts/publish-cli/inject-clamp.js <directory> [--dry-run]');
    process.exit(2);
  }
  rootDir = path.resolve(rootDir);
  if (!fs.existsSync(rootDir) || !fs.statSync(rootDir).isDirectory()) {
    console.error('ERROR: not a directory: ' + rootDir);
    process.exit(2);
  }

  console.log('inject-clamp.js — ' + (dryRun ? 'DRY-RUN' : 'APPLY'));
  console.log('  root: ' + rootDir);
  console.log('');

  var deckHtmlPaths = [];
  walkDecksDir(rootDir, deckHtmlPaths);
  console.log('Found ' + deckHtmlPaths.length + ' deck.html files');
  console.log('');

  var counts = { 'injected': 0, 'would-inject': 0, 'skip-already-injected': 0, 'skip-no-body-close': 0, 'skip-read-error': 0, 'write-error': 0 };
  var notes = [];
  deckHtmlPaths.forEach(function (p, idx) {
    var r = processFile(p, dryRun);
    counts[r.action] = (counts[r.action] || 0) + 1;
    if (r.action === 'write-error' || r.action === 'skip-read-error' || r.action === 'skip-no-body-close') {
      notes.push('  ' + r.action + '  ' + p + (r.note ? '  // ' + r.note : ''));
    }
    if ((idx + 1) % 100 === 0) console.log('  processed ' + (idx + 1) + '/' + deckHtmlPaths.length);
  });

  console.log('');
  console.log('=== Summary ===');
  Object.keys(counts).forEach(function (k) {
    if (counts[k] > 0) console.log('  ' + k + ':  ' + counts[k]);
  });
  if (notes.length > 0) {
    console.log('');
    console.log('=== Errors / unusual cases ===');
    notes.forEach(function (n) { console.log(n); });
  }
  process.exit((counts['write-error'] || 0) > 0 ? 1 : 0);
}

if (require.main === module) {
  main();
}

module.exports = { processFile: processFile, MARKER: MARKER, CLAMP_SCRIPT: CLAMP_SCRIPT };
